/**************************************************************************/
/*                                                                        */
/*  PORT SPECIFIC C INFORMATION                            RELEASE        */
/*                                                                        */
/*    tx_port_offset_check.c                           Cortex-R5/GNU      */
/*                                                                        */
/*  DESCRIPTION                                                           */
/*                                                                        */
/*    Compile-time verification of the TX_THREAD structure offsets that    */
/*    this port's assembly reaches by hard-coded displacement.  The file   */
/*    emits no code; it exists purely so that a layout change becomes a    */
/*    build failure.                                                      */
/*                                                                        */
/*    Why this is needed: tx_thread_schedule.S,                            */
/*    tx_thread_system_return.S and tx_thread_context_restore.S read and   */
/*    write the per-thread VFP enable flag as [thread, #144].  Nothing in  */
/*    the toolchain connects that literal to the C structure, so adding a  */
/*    member, enabling an option that adds one, or reordering the port     */
/*    extensions would silently retarget those accesses at an unrelated    */
/*    field -- corrupting thread state in a way that is extremely hard to    */
/*    diagnose from the symptom.  The offset was measured at 144 for the   */
/*    default build and is asserted here.                                  */
/*                                                                        */
/*    NOTE: this port has no CMake build of its own, so this file takes     */
/*    effect only in builds that compile everything under src/.  It is       */
/*    still worthwhile: it emits no code, costs nothing, and protects every  */
/*    build that does pick it up.                                          */
/*                                                                        */
/*    A negative array dimension is used rather than _Static_assert        */
/*    because this project targets C99, where _Static_assert does not      */
/*    exist.  If an assertion below fails, the compiler reports a negative  */
/*    or zero-sized array for the named typedef.                           */
/*                                                                        */
/**************************************************************************/

#include "tx_api.h"
#include <stddef.h>

/* Offset of the VFP enable flag as encoded in this port's assembly.
   Overridable only so that the assertion itself can be tested.  */

#ifndef TX_PORT_VFP_ENABLE_OFFSET
#define TX_PORT_VFP_ENABLE_OFFSET   144
#endif

typedef char
tx_port_assert_vfp_enable_offset_is_144[
    (offsetof(TX_THREAD, tx_thread_vfp_enable) == TX_PORT_VFP_ENABLE_OFFSET)
        ? 1 : -1];

/* The stack pointer is read as [thread, #8] by tx_thread_schedule.S and
   written by tx_thread_system_return.S, and the run counter as
   [thread, #4].  Assert those too, since they are on the context-switch
   critical path.  */

typedef char
tx_port_assert_stack_ptr_offset_is_8[
    (offsetof(TX_THREAD, tx_thread_stack_ptr) == 8) ? 1 : -1];

typedef char
tx_port_assert_run_count_offset_is_4[
    (offsetof(TX_THREAD, tx_thread_run_count) == 4) ? 1 : -1];
